import { useState } from "react";
import { Button, Card, FormPart, Input } from "ui";

const noop = () => {};
const keep = { leaving: false, held: false, onGone: noop } as const;

/** Add opens a part to its own height; Remove fades it, then the gap settles. Nothing below jumps. */
export const AddAndRemove = () => {
  const [parts, setParts] = useState([{ id: 1, word: "fab_lead", added: false }]);
  const [gone, setGone] = useState<number | null>(null);
  return (
    <div style={{ maxWidth: 520, display: "flex", flexDirection: "column", gap: 12 }}>
      <Card>
        {parts.map((p) => (
          <FormPart
            key={p.id}
            appear={p.added}
            {...keep}
            leaving={gone === p.id}
            onGone={() => {
              setParts((all) => all.filter((x) => x.id !== p.id));
              setGone(null);
            }}
          >
            <div style={{ display: "flex", gap: 10, padding: "10px 20px", alignItems: "center" }}>
              <div style={{ flex: 1 }}>
                <Input defaultValue={p.word} aria-label="Word" />
              </div>
              <Button size="sm" variant="outline" onClick={() => setGone(p.id)}>
                Remove
              </Button>
            </div>
          </FormPart>
        ))}
      </Card>
      <div>
        <Button
          size="sm"
          variant="outline"
          onClick={() => setParts((all) => [...all, { id: Date.now(), word: "", added: true }])}
        >
          Add a word
        </Button>
      </div>
    </div>
  );
};

/** A form's parts as it opens: simply there. */
export const Opened = () => (
  <Card>
    <FormPart {...keep}>
      <div style={{ padding: "12px 20px", fontSize: 14.5 }}>Laser cutter · Operator</div>
    </FormPart>
    <FormPart {...keep}>
      <div style={{ padding: "12px 20px", fontSize: 14.5 }}>Wood shop · Supervisor</div>
    </FormPart>
  </Card>
);
